  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Creates a new IPO application for a retail customer.
   *          Checks eligibility, validates inputs, and ensures no approved application
   *          exists for the same company.
   * Algorithm:
   *   1. Check if this.isEligibleForIPO() returns true; if not, return false.
   *   2. Validate inputs: shares > 0, amount > 0, doc is not null.
   *      If any invalid, return false.
   *   3. Iterate through this.applications to check if any application with
   *      app.company.name == company.name and app.status == APPROVAL exists.
   *      If such an application exists, return false.
   *   4. Create a new Application object with the given parameters:
   *      - company = company
   *      - share = shares
   *      - amountOfMoney = amount
   *      - allowance = doc
   *      - status = PENDING
   *      - customer = this
   *      - emails = empty list
   *   5. Add the new Application to this.applications list.
   *   6. Return true.
   * Related Features: Customer.applications, Customer.isEligibleForIPO(),
   *                   Application.status, Application.company.name,
   *                   Application.allowance, Application.share, Application.amountOfMoney
   * Related Classes: Application, Company, Document, ApplicationStatus
   * Input:
   *   - company : Company - the target company for the IPO application
   *   - shares : int - number of shares requested (must be > 0)
   *   - amount : double - payment amount (must be > 0)
   *   - doc : Document - legal allowance document (must be non-null)
   * Output: boolean - true if the application is created successfully, false otherwise.
   * Pre-condition: The customer is eligible for IPO (canApplyForIPO is true).
   * Post-condition: If successful, a new PENDING Application is added to the customer's
   *                 application list.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    // 1. Check eligibility
    if (!isEligibleForIPO()) {
      return false;
    }
    
    // 2. Validate inputs
    if (shares <= 0 || amount <= 0.0 || doc == null) {
      return false;
    }
    
    // 3. Check for existing approved application for the same company
    for (Application app : getApplications()) {
      if (app.getCompany().getName().equals(company.getName()) && 
          app.getStatus() == ApplicationStatus.APPROVAL) {
        return false;
      }
    }
    
    // 4. Create new Application using factory
    IpoFactory factory = IpoFactory.eINSTANCE;
    Application newApp = factory.createApplication();
    newApp.setCompany(company);
    newApp.setShare(shares);
    newApp.setAmountOfMoney(amount);
    newApp.setAllowance(doc);
    newApp.setStatus(ApplicationStatus.PENDING);
    newApp.setCustomer(this);
    newApp.getEmails().clear();
    
    // 5. Add to applications list
    getApplications().add(newApp);
    
    // 6. Return success
    return true;
  }

